{
  "calculations": [
    {
      "name": "Power Dissipation (P_D)",
      "formula": "(V_IN - V_OUT) * I_OUT",
      "inputs": {
        "V_IN": {
          "ref": "q1",
          "meaning": "輸入電壓",
          "unit": "V"
        },
        "V_OUT": {
          "ref": "q2",
          "meaning": "輸出電壓",
          "unit": "V"
        },
        "I_OUT": {
          "ref": "q3",
          "meaning": "輸出電流",
          "unit": "A"
        }
      },
      "stated_result": 10.5,
      "unit": "W"
    },
    {
      "name": "Junction Temperature (T_J)",
      "formula": "T_A + (P_D * theta_JA)",
      "inputs": {
        "T_A": {
          "ref": "q4",
          "meaning": "環境溫度",
          "unit": "°C"
        },
        "P_D": {
          "from_calc": "Power Dissipation (P_D)"
        },
        "theta_JA": {
          "ref": "q6",
          "meaning": "接面到環境熱阻",
          "unit": "°C/W"
        }
      },
      "stated_result": 312.5,
      "unit": "°C"
    },
    {
      "name": "Overtemperature Margin",
      "formula": "T_J - T_J_max",
      "inputs": {
        "T_J": {
          "from_calc": "Junction Temperature (T_J)"
        },
        "T_J_max": {
          "ref": "q5",
          "meaning": "接面溫度上限",
          "unit": "°C"
        }
      },
      "stated_result": 187.5,
      "unit": "°C"
    },
    {
      "name": "Switching Regulator Power Loss (Est)",
      "formula": "(V_OUT * I_OUT / Efficiency) - (V_OUT * I_OUT)",
      "inputs": {
        "V_OUT": {
          "ref": "q2",
          "meaning": "輸出電壓",
          "unit": "V"
        },
        "I_OUT": {
          "ref": "q3",
          "meaning": "輸出電流",
          "unit": "A"
        },
        "Efficiency": {
          "assume": 0.9,
          "meaning": "假設開關穩壓器效率",
          "unit": "ratio"
        }
      },
      "stated_result": 0.83,
      "unit": "W"
    },
    {
      "name": "Switching Regulator Junction Temp (Est)",
      "formula": "T_A + (P_Loss_Switch * theta_JA)",
      "inputs": {
        "T_A": {
          "ref": "q4",
          "meaning": "環境溫度",
          "unit": "°C"
        },
        "P_Loss_Switch": {
          "from_calc": "Switching Regulator Power Loss (Est)"
        },
        "theta_JA": {
          "ref": "q6",
          "meaning": "接面到環境熱阻",
          "unit": "°C/W"
        }
      },
      "stated_result": 70.75,
      "unit": "°C"
    },
    {
      "name": "Reduced VIN Power Dissipation (Est)",
      "formula": "(V_IN_New - V_OUT) * I_OUT",
      "inputs": {
        "V_IN_New": {
          "assume": 6,
          "meaning": "假設降低後的輸入電壓",
          "unit": "V"
        },
        "V_OUT": {
          "ref": "q2",
          "meaning": "輸出電壓",
          "unit": "V"
        },
        "I_OUT": {
          "ref": "q3",
          "meaning": "輸出電流",
          "unit": "A"
        }
      },
      "stated_result": 1.5,
      "unit": "W"
    },
    {
      "name": "Reduced VIN Junction Temp (Est)",
      "formula": "T_A + (P_D_Reduced * theta_JA)",
      "inputs": {
        "T_A": {
          "ref": "q4",
          "meaning": "環境溫度",
          "unit": "°C"
        },
        "P_D_Reduced": {
          "from_calc": "Reduced VIN Power Dissipation (Est)"
        },
        "theta_JA": {
          "ref": "q6",
          "meaning": "接面到環境熱阻",
          "unit": "°C/W"
        }
      },
      "stated_result": 87.5,
      "unit": "°C"
    },
    {
      "name": "Required Total Thermal Resistance",
      "formula": "(T_J_max - T_A) / P_D",
      "inputs": {
        "T_J_max": {
          "ref": "q5",
          "meaning": "接面溫度上限",
          "unit": "°C"
        },
        "T_A": {
          "ref": "q4",
          "meaning": "環境溫度",
          "unit": "°C"
        },
        "P_D": {
          "from_calc": "Power Dissipation (P_D)"
        }
      },
      "stated_result": 7.14,
      "unit": "°C/W"
    }
  ],
  "schedules": []
}
